public class TaskEntryPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            TaskEntryPanel panel = new TaskEntryPanel();
            javax.swing.JTextField entry = (javax.swing.JTextField) find(panel, "entry");
            javax.swing.JButton add = (javax.swing.JButton) find(panel, "add");
            java.awt.Component label = find(panel, "count");

            check("no tasks at the start", "[]", panel.tasks().toString());
            check("label at the start", "0 task(s)", textOf(label));

            entry.setText("milk");
            add.doClick();
            check("the button adds the task", "[milk]", panel.tasks().toString());
            check("the field is cleared", "", entry.getText());
            check("the label counts one task", "1 task(s)", textOf(label));

            entry.setText("  eggs  ");
            entry.postActionEvent();
            check("Enter in the field adds a trimmed task",
                    "[milk, eggs]", panel.tasks().toString());

            entry.setText("   ");
            add.doClick();
            check("blank input is ignored", 2, panel.tasks().size());

            entry.setText("");
            entry.postActionEvent();
            check("empty input is ignored", "2 task(s)", textOf(label));

            entry.setText("bread");
            add.doClick();
            check("third task", "3 task(s)", textOf(label));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

