import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class TaskEntryPanel extends JPanel implements ActionListener {

    private final JTextField entry = new JTextField(12);
    private final JButton add = new JButton("Add");
    private final JLabel count = new JLabel("0 task(s)");
    private final List<String> tasks = new ArrayList<>();

    public TaskEntryPanel() {
        entry.setName("entry");
        add.setName("add");
        count.setName("count");
        add(entry);
        add(add);
        add(count);
        entry.addActionListener(this);
        add.addActionListener(this);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        String text = entry.getText().trim();
        if (text.isEmpty()) {
            return;
        }
        tasks.add(text);
        entry.setText("");
        count.setText(tasks.size() + " task(s)");
    }

    public List<String> tasks() {
        return new ArrayList<>(tasks);
    }
}
